-- Generated by Claude Code — Feed-Platzierung bezahlter Promotionen.
-- Liefert pro aktiver Promotion (bezahlt, genehmigt, im Zeitraum, Event noch
-- nicht vorbei) Event und Platzierung. Die Apps setzen das Event damit an die
-- gebuchte Stelle (Hero, Empfehlungs-Schiene, "Konzerte entdecken", Listen).
-- Nur IDs und Platzierung, keine Zahlungs- oder Anfragerdaten.
create function active_event_promotions()
returns table (event_id uuid, placement text, ends_at timestamptz)
language sql
security definer
set search_path = public
stable
as $$
  select p.event_id, p.placement, p.ends_at
  from event_promotions p
  join events e on e.id = p.event_id
  where p.status = 'approved'
    and p.payment_status = 'paid'
    and p.starts_at <= now()
    and (p.ends_at is null or p.ends_at > now())
    and e.status = 'scheduled'
    and e.start_datetime > now()
  order by p.starts_at;
$$;

revoke all on function active_event_promotions() from public;
grant execute on function active_event_promotions() to anon, authenticated;
